// Foundation checks: difficulty modes, save slots, key rebinding, interiors, hooks.
const { chromium } = require('playwright');
const SHOTS = process.env.SHOTS || '/tmp/shots';
let fails = 0; const check = (c, m) => { console.log((c ? '  ok  ' : '  FAIL ') + m); if (!c) fails++; };
(async () => {
  const b = await chromium.launch(); const page = await b.newPage({ viewport: { width: 1366, height: 768 } });
  const errs = []; page.on('pageerror', (e) => errs.push(e.message)); page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
  await page.goto('http://localhost:8123/index.html?view=2d'); await page.evaluate(() => localStorage.clear()); await page.reload(); await page.waitForTimeout(400);
  const ev = (f, a) => page.evaluate(f, a);
  console.log('# New game screen');
  await page.click('#b-new'); await page.waitForTimeout(150);
  await page.click('[data-mode=hard]'); await page.waitForTimeout(80);
  await page.fill('#ng-seed', 'wolf moon'); await page.waitForTimeout(50);
  check(await ev(() => document.getElementById('ng-seed').value === 'WOLFMOON'), 'seed field keeps letters/digits, upper-case');
  await page.screenshot({ path: SHOTS + '/f-newgame.png' });
  await page.click('[data-mode=custom]'); await page.waitForTimeout(80);
  check(await ev(() => document.querySelectorAll('[data-c]').length === 6), 'custom mode shows 6 sliders');
  await page.screenshot({ path: SHOTS + '/f-newgame-custom.png' });
  await page.click('[data-mode=hard]'); await page.waitForTimeout(80);
  await ev(() => { for (const id of ['ng-intro', 'ng-guided']) { const i = document.getElementById(id); if (i && i.checked) i.click(); } });
  await page.click('#ng-start'); await page.waitForTimeout(300);
  let st = await ev(() => ({ mode: NW.G.state.mode.id, n: NW.G.finalNight(), seed: NW.G.state.seedText, slot: NW.G.state.slot, seedNum: NW.G.state.seed }));
  check(st.mode === 'hard' && st.n === 14 && st.seed === 'WOLFMOON' && st.slot === 1, 'hard run: 14 nights, seed WOLFMOON, slot 1 (' + JSON.stringify(st) + ')');
  check(await ev(() => NW.G.state.records.reports.some((r) => /assigned for 14 nights/.test(r.text))), 'HQ records mention 14 nights');
  const seedA = st.seedNum;
  // same seed reproduces the world
  const world1 = await ev(() => JSON.stringify([NW.G.state.records.permits.map((p) => p.name), NW.G.state.dayEvents.map((e) => e.type + e.area)]));
  await ev(() => NW.G.save('manual'));
  console.log('# Slots');
  await ev(() => NW.UI.showMenu());
  await page.click('#b-new'); await page.waitForTimeout(150);
  check(await ev(() => document.querySelector('input[name=ng-slot]:checked').value === '2'), 'second run goes to free slot 2');
  await page.click('[data-mode=standard]'); await page.fill('#ng-seed', 'wolfmoon');
  await ev(() => { for (const id of ['ng-intro', 'ng-guided']) { const i = document.getElementById(id); if (i && i.checked) i.click(); } });
  await page.click('#ng-start'); await page.waitForTimeout(300);
  st = await ev(() => ({ mode: NW.G.state.mode.id, slot: NW.G.state.slot, seed: NW.G.state.seed }));
  check(st.slot === 2 && st.mode === 'standard' && st.seed === seedA, 'slot 2 standard with the same seed number');
  const world2 = await ev(() => JSON.stringify([NW.G.state.records.permits.map((p) => p.name), NW.G.state.dayEvents.map((e) => e.type + e.area)]));
  check(world1 === world2, 'same seed gives the same permits and day events');
  await ev(() => { NW.G.state.time.day = 3; NW.G.save('manual'); NW.UI.showMenu(); });
  check(await ev(() => NW.Save.exists(1) && NW.Save.exists(2) && !NW.Save.exists(3)), 'slots 1 and 2 hold runs, 3 empty');
  check(await ev(() => NW.Save.latest() === 2), 'latest slot is 2');
  await page.click('#b-load'); await page.waitForTimeout(150);
  check(await ev(() => document.querySelectorAll('.slot-row').length === 3), 'load screen lists 3 slots');
  await page.screenshot({ path: SHOTS + '/f-slots.png' });
  await page.click('[data-load="1"]'); await page.waitForTimeout(250);
  st = await ev(() => ({ mode: NW.G.state.mode.id, slot: NW.G.state.slot, day: NW.G.state.time.day, playing: NW.G.mode }));
  check(st.slot === 1 && st.mode === 'hard' && st.day === 1 && st.playing === 'play', 'loading slot 1 restores the hard run');
  await ev(() => { NW.G.state.time.min = 9 * 60; NW.G.save('manual'); });
  check(await ev(() => NW.Save.read(2).state.time.day === 3), 'slot 2 untouched by saving slot 1');
  await ev(() => NW.UI.showMenu());
  check(await ev(() => /Slot 1 · Hard/.test(document.getElementById('save-info').textContent)), 'menu Continue shows the latest slot: ' + await ev(() => document.getElementById('save-info').textContent));
  // legacy key compatibility: slot 1 uses the original key
  check(await ev(() => !!localStorage.getItem('nightwatch.save') && !!localStorage.getItem('nightwatch.save.2')), 'slot 1 keeps the legacy key; slot 2 has its own');
  console.log('# Key rebinding');
  await page.click('#b-continue'); await page.waitForTimeout(250);
  await ev(() => NW.UI.open('settings')); await page.waitForTimeout(100);
  await page.click('[data-bind=interact][data-slot="0"]'); await page.waitForTimeout(60);
  check(await ev(() => !!NW.UI._capture), 'clicking a key button starts capture');
  await page.keyboard.press('KeyQ'); await page.waitForTimeout(80);
  check(await ev(() => NW.Keys.binds.interact[0] === 'KeyQ' && JSON.parse(localStorage.getItem('nightwatch.keys')).interact[0] === 'KeyQ'), 'interact rebound to Q and saved');
  await page.click('[data-bind=map][data-slot="0"]'); await page.keyboard.press('KeyQ'); await page.waitForTimeout(60);
  check(await ev(() => NW.Keys.binds.map[0] === 'KeyQ' && NW.Keys.binds.interact[0] === null), 'binding Q to map removes it from interact');
  await page.screenshot({ path: SHOTS + '/f-settings-keys.png' });
  await page.click('[data-bind=interact][data-slot="0"]'); await page.keyboard.press('KeyR'); await page.waitForTimeout(60);
  await page.click('[data-bind=map][data-slot="0"]'); await page.keyboard.press('Digit3'); await page.waitForTimeout(60);
  check(await ev(() => NW.Keys.binds.map[0] === 'KeyQ'), 'digits are refused as bindings');
  await ev(() => NW.UI.closeAll());
  await page.keyboard.press('KeyQ'); await page.waitForTimeout(80);
  check(await ev(() => NW.UI.isOpen('map')), 'Q now opens the map');
  await page.keyboard.press('KeyQ'); await page.waitForTimeout(80);
  check(await ev(() => !NW.UI.isOpen('map')), 'Q closes the map');
  await page.keyboard.press('KeyM'); await page.waitForTimeout(80);
  check(await ev(() => !NW.UI.isOpen('map')), 'M no longer opens the map');
  // R as interact: stand at the stove
  await ev(() => { NW.G.enterArea('room_main', 64, 80, 'up'); });
  await page.waitForTimeout(150);
  const f = await ev(() => NW.G.focus && NW.G.focus.name);
  const fuel0 = await ev(() => NW.G.state.stove.fuel);
  await ev(() => { NW.G.state.woodbox = 4; });
  await page.keyboard.press('KeyR'); await page.waitForTimeout(100);
  check(await ev((f0) => NW.G.state.stove.fuel > f0, fuel0), 'R performs the first action (' + f + ')');
  check(await ev(() => /R/.test(document.querySelector('#prompt .prow .k').textContent)), 'prompt shows the rebound key');
  await ev(() => { NW.Keys.reset(); NW.Keys.save(); });
  console.log('# Interiors');
  await ev(() => {
    NW.World.registerArea('test_hut', { name: 'Test Hut', theme: 'plank', shelter: 12, dark: 0.5, mapAt: { area: 'f_2_1', x: 200, y: 120 },
      map: ['TTTTTTTTTT', 'FFFFFFFFFF', '|........|', '|........|', '|........|', '____dd____'],
      objs: (px) => [{ x: px(3), y: px(3), cx: px(3) - 6, cy: px(3) - 6, cw: 12, ch: 6, solid: true, name: 'Odd crate', draw: (g) => { g.fillStyle = '#a06a40'; g.fillRect(px(3) - 6, px(3) - 10, 12, 10); }, actions: () => [{ label: 'Kick it', run: () => { NW.testKicked = true; } }] }],
      exits: [{ x: 64, y: 86, w: 32, h: 10, to: 'f_2_1', tx: 200, ty: 130, dir: 'down' }] });
    NW.G.enterArea('test_hut', 80, 70, 'up');
  });
  await page.waitForTimeout(200);
  st = await ev(() => ({ kind: NW.G.area.kind, focus: NW.G.focus && NW.G.focus.name, temp: NW.Survival.envTemp(), w: NW.G.state.weather.temp }));
  check(st.kind === 'interior', 'interior area is kind interior');
  await ev(() => { NW.G.state.player.x = 52; NW.G.state.player.y = 64; NW.G.state.player.dir = 'up'; }); await page.waitForTimeout(120);
  st.focus = await ev(() => NW.G.focus && NW.G.focus.name);
  check(st.focus === 'Odd crate', 'custom object focus: ' + st.focus);
  await page.keyboard.press('KeyE'); await page.waitForTimeout(60);
  check(await ev(() => NW.testKicked === true), 'custom object action runs');
  await page.screenshot({ path: SHOTS + '/f-interior.png' });
  check(await ev(() => NW.G.save('manual') && NW.Save.read(1).state.player.area === 'test_hut'), 'save inside an interior validates');
  await page.keyboard.down('KeyS'); await page.waitForTimeout(900); await page.keyboard.up('KeyS');
  await ev(() => { NW.G.state.player.x = 80; NW.G.state.player.y = 80; }); await page.keyboard.down('KeyS'); await page.waitForTimeout(500); await page.keyboard.up('KeyS');
  check(await ev(() => NW.G.area.id === 'f_2_1'), 'walking out the door returns to the forest (' + await ev(() => NW.G.area.id) + ')');
  console.log('# Hooks');
  await ev(() => { NW.Hooks.on('objects', (aid) => aid === 'f_2_1' ? [{ type: 'mod', x: 220, y: 140, name: 'Mod stone', draw: (g) => { g.fillStyle = '#888'; g.fillRect(214, 134, 12, 6); }, actions: () => [{ label: 'Touch', run: () => { NW.touched = 1; } }], solid: { x: 214, y: 134, w: 12, h: 6 } }] : []); NW.G.state.player.x = 220; NW.G.state.player.y = 156; NW.G.state.player.dir = 'up'; });
  await page.waitForTimeout(150);
  check(await ev(() => NW.G.focus && NW.G.focus.name === 'Mod stone'), 'module object gets focus');
  check(await ev(() => NW.World.blocked(NW.G.area, 216, 135, 4, 4)), 'module object collides');
  check(await ev(() => (NW.hookErrors || []).length === 0), 'no hook errors');
  console.log('errors:', errs.slice(0, 5)); console.log(fails ? fails + ' FAILURES' : 'ALL PASSED');
  await b.close(); process.exit(fails ? 1 : 0);
})();
